(function(){
'use strict';
function mountMatrixGuide(options={}){
const G=window.MatrixGuideMath,host=document.getElementById('guided-workspace');if(!host)return;
let index=0,progress=1,frame=null,timer=null,playing=false;const lifecycle=new AbortController();
const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches||false;
const el=id=>document.getElementById(id);
function matrix(original){const v=original?[1,0,0,1]:G.matrix;return`<div class="guide-matrix">${v.map((n,i)=>`<span class="${i%2===0?'first':'second'}" ${!original?`data-guide-column="${i%2}"`:''}>${n}</span>`).join('')}</div>`;}
host.innerHTML=`<div class="guide-layout"><section class="guide-explanation"><span class="eyebrow" id="guide-step-label">Step 1 of 7</span><h2 id="guide-title"></h2><p id="guide-text"></p><div class="guide-columns"><div class="guide-matrix-box"><div class="guide-matrix-title">Original directions · I</div>${matrix(true)}</div><div class="guide-matrix-box"><div class="guide-matrix-title">New directions · A</div>${matrix(false)}</div></div><div class="guide-column-key"><span class="first">First column: what happens to 1 right-step.</span><span class="second">Second column: what happens to 1 up-step.</span></div><p class="guide-input"><strong>Input vector: v = (1, 2).</strong> It uses 1 copy of (1, 0) and 2 copies of (0, 1).</p><div class="guide-counts"><div class="guide-count"><span>1</span>copy of the first direction</div><div class="guide-count"><span>2</span>copies of the second direction</div></div><div id="guide-equation" class="guide-equation"></div><nav class="guide-step-list" aria-label="Guided lesson steps">${G.STEPS.map((s,i)=>`<button data-guide-step="${i}" aria-label="Step ${i+1}: ${s.title}">${i+1}</button>`).join('')}</nav><p class="guide-note">The two columns change the directions. The original coefficients, 1 and 2, tell us how many copies of each new direction to use. The graph starts at the origin (0, 0); this is the starting position, not the input vector or a lesson step number.</p></section><section class="guide-plot-card" aria-label="Diagram for the current step"><div class="guide-legend"><span><i class="swatch"></i>First direction</span><span><i class="swatch blue"></i>Second direction</span><span><i class="swatch orange"></i>Position / result</span></div><svg id="guide-svg" role="img" aria-label="Matrix transformation steps"></svg><div id="guide-phase" class="guide-phase"></div><div class="guide-controls"><button id="guide-prev" class="btn">Previous</button><button id="guide-play" class="btn primary">Play all steps</button><button id="guide-next" class="btn">Next</button><span id="guide-counter" class="guide-counter"></span></div><div class="guide-note">Use Next to read at your own pace. Playback pauses between steps; Pause holds the current diagram.</div></section></div>`;
function phase(){if(index===0)return progress<1?'Follow the original route: one right-step, then two up-steps.':'Original endpoint: (1, 2).';if(index===1)return'First column (1, 0): the right-step stays the same.';if(index===2)return progress<1?'The old up-step moves toward its new direction.':'Second column (1, 1): one new up-step adds 1 right and 1 up.';if(index===3)return'Use 1 copy of (1, 0), then 2 copies of (1, 1).';if(index===4)return progress<1?'First move: use the new right-step once.':'After the first move: (1, 0).';if(index===5)return progress<.5?'New up-step 1: add 1 right and 1 up.':progress<1?'New up-step 2: add another 1 right and 1 up.':'After both diagonal moves: (3, 2).';return'Final result: 3 right and 2 up, so Av = (3, 2).';}
function controls(){options.onStep?.(index);const s=G.STEPS[index];el('guide-step-label').textContent=`Step ${index+1} of ${G.STEPS.length}`;el('guide-title').textContent=s.title;el('guide-text').textContent=s.text;el('guide-equation').textContent=s.formula;el('guide-counter').textContent=`${index+1} / ${G.STEPS.length}`;el('guide-prev').disabled=index===0;el('guide-next').disabled=index===G.STEPS.length-1||options.canVisitStep?.(index+1)===false;el('guide-play').textContent=playing?'Pause':'Play all steps';document.querySelectorAll('[data-guide-step]').forEach(n=>n.setAttribute('aria-current',Number(n.dataset.guideStep)===index?'step':'false'));document.querySelectorAll('[data-guide-step]').forEach(n=>n.disabled=options.canVisitStep?.(Number(n.dataset.guideStep))===false);document.querySelectorAll('[data-guide-column]').forEach(n=>n.setAttribute('data-active',String((index===1||index===4)&&n.dataset.guideColumn==='0'||(index===2||index===5)&&n.dataset.guideColumn==='1')));}
function draw(){const svg=el('guide-svg'),width=Math.max(280,svg.getBoundingClientRect().width),height=Math.min(450,Math.max(330,width*.84)),left=46,right=24,top=30,bottom=55,scale=Math.min((width-left-right)/4.2,(height-top-bottom)/3.4),X=n=>left+(n+.6)*scale,Y=n=>height-bottom-(n+.6)*scale;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.style.height=height+'px';const scene=G.scene(index,progress),path=(a,b)=>`M${X(a[0])} ${Y(a[1])}L${X(b[0])} ${Y(b[1])}`;
let html=`<defs>${[['first','#087e73'],['second','#3658d4'],['result','#b8650b']].map(([id,c])=>`<marker id="guide-tip-${id}" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="${c}"/></marker>`).join('')}</defs><rect width="${width}" height="${height}" fill="#fafcff"/>`;
for(let n=0;n<=3;n++)html+=`<path d="${path([n,-.4],[n,2.6])}" stroke="#e2eaf4" stroke-width="1"/>`;for(let n=0;n<=2;n++)html+=`<path d="${path([-.4,n],[3.4,n])}" stroke="#e2eaf4" stroke-width="1"/>`;
html+=`<path d="${path([-.4,0],[3.4,0])} ${path([0,-.4],[0,2.6])}" stroke="#90a4bc" stroke-width="1.4"/><text x="${X(3.4)}" y="${Y(0)-12}" text-anchor="end" font-size="14" fill="#536b85">x</text><text x="${X(0)+12}" y="${Y(2.6)+5}" font-size="14" fill="#536b85">y</text>`;
for(let n=0;n<=3;n++)html+=`<text x="${X(n)}" y="${Y(0)+20}" text-anchor="middle" font-size="13" fill="#536b85">${n}</text>`;for(let n=1;n<=2;n++)html+=`<text x="${X(0)-11}" y="${Y(n)+5}" text-anchor="end" font-size="13" fill="#536b85">${n}</text>`;
const color={first:'#087e73',second:'#3658d4',result:'#b8650b'};
function arrow(a,b,c,sw=3,opacity=1,dashed=false){if(a.every((n,i)=>Math.abs(n-b[i])<1e-7))return;html+=`<path d="${path(a,b)}" stroke="${color[c]}" stroke-width="${sw}" opacity="${opacity}" ${dashed?'stroke-dasharray="6 5"':''} marker-end="url(#guide-tip-${c})"/>`;}
const labelBoxes=[];
function label(p,text,dx=12,dy=-12,anchor='start'){
const w=text.length*8,start=X(p[0])+dx-(anchor==='end'?w:anchor==='middle'?w/2:0);let box;
for(const offset of[0,-22,22,-44,44]){const x=Math.max(8,Math.min(width-w-8,start)),y=Math.max(22,Math.min(height-10,Y(p[1])+dy+offset));box={x,y,w};if(!labelBoxes.some(b=>x<b.x+b.w+5&&x+w+5>b.x&&Math.abs(y-b.y)<19))break;}
labelBoxes.push(box);html+=`<text x="${box.x}" y="${box.y}" font-size="14" fill="#243e5c">${text}</text>`;}
if(index===0){arrow([0,0],[1,0],'first',3,.65);arrow([0,0],[0,1],'second',3,.65);label([1,0],'e₁ = (1, 0)',0,43,'middle');label([0,1],'e₂ = (0, 1)',12,-12);arrow([0,0],[1,2],'result',2,.25,true);label([1,2],'v = (1, 2)',12,-13);}if(index>=1&&index<=3){if(index===2){arrow([0,0],[0,1],'second',2,.25,true);label([0,1],'old (0, 1)',12,-30);}arrow([0,0],scene.right,'first',index===1?5:3,index===2?.4:1);arrow([0,0],scene.up,'second',index===2?5:3,index===1?.4:1);label([1,0],'(1, 0)',0,43,'middle');if(index===2&&progress<1)label(scene.up,'moving up-step',12,-12);else label(scene.up,index===1?'(0, 1)':'(1, 1)',12,-12);}
for(const seg of scene.segments){const opacity=index===6?.32:1;arrow(seg.from,seg.to,seg.color,4,opacity);const complete=Math.hypot(seg.to[0]-seg.from[0],seg.to[1]-seg.from[1])>=Math.hypot(seg.color==='first'?1:index===0?0:1,seg.color==='first'?0:1)-1e-6;if(seg.color==='second'&&complete&&index!==6){const mx=(seg.from[0]+seg.to[0])/2,my=(seg.from[1]+seg.to[1])/2;html+=`<circle cx="${X(mx)+14}" cy="${Y(my)+10}" r="10" fill="#3658d4"/><text x="${X(mx)+14}" y="${Y(my)+15}" text-anchor="middle" font-size="13" fill="#fff">${seg.copy}</text>`;}}
if(index===0||index>=4){const p=scene.position;html+=`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="7" fill="#b8650b" stroke="#fff" stroke-width="2"/>`;if(progress>=1&&index!==0&&index!==6)label(p,`(${p[0]}, ${p[1]})`,-12,-14,'end');}
if(index===4)label([1,0],'1 right, 0 up',0,43,'middle');
if(index===6){arrow([0,0],[3,2],'result',4);html+=`<path d="${path([0,0],[3,0])} ${path([3,0],[3,2])}" fill="none" stroke="#b8650b" stroke-width="2" stroke-dasharray="5 4"/>`;for(let x=1;x<=3;x++)html+=`<circle cx="${X(x)}" cy="${Y(0)}" r="4" fill="#b8650b"/>`;for(let y=1;y<=2;y++)html+=`<circle cx="${X(3)}" cy="${Y(y)}" r="4" fill="#b8650b"/>`;label([1.5,0],'3 right',0,43,'middle');label([3,1],'2 up',-10,0,'end');label([3,2],'Av = (3, 2)',-10,-17,'end');}
svg.innerHTML=html;svg.setAttribute('aria-label',G.STEPS[index].title+' '+phase());el('guide-phase').textContent=phase();}
function halt(refresh=true){if(frame!==null)cancelAnimationFrame(frame);if(timer!==null)clearTimeout(timer);frame=null;timer=null;playing=false;if(refresh)controls();}
function go(i,auto=false){if(options.canVisitStep?.(i)===false){halt();return;}if(!Number.isInteger(i)||i<0||i>=G.STEPS.length)throw new Error('Step must be an integer from 0 to 6.');if(frame!==null)cancelAnimationFrame(frame);if(timer!==null)clearTimeout(timer);frame=null;timer=null;index=i;progress=0;controls();const duration=[0,2,4,5].includes(i)?(i===5?2200:1400):0,start=performance.now();function tick(now){progress=reduced||duration===0?1:Math.max(0,Math.min(1,(now-start)/duration));draw();if(progress<1)frame=requestAnimationFrame(tick);else{frame=null;if(auto&&playing){if(index===G.STEPS.length-1){playing=false;controls();}else timer=setTimeout(()=>{timer=null;if(playing)go(index+1,true);},4200);}}}frame=requestAnimationFrame(tick);}
el('guide-prev').onclick=()=>{halt();if(index>0)go(index-1);};el('guide-next').onclick=()=>{halt();if(index<G.STEPS.length-1)go(index+1);};document.querySelectorAll('[data-guide-step]').forEach(n=>n.onclick=()=>{halt();go(Number(n.dataset.guideStep));});el('guide-play').onclick=()=>{if(playing){halt();return;}playing=true;go(index===G.STEPS.length-1?0:index,true);};
window.MatrixGuide={pause:halt,refresh:controls,read:()=>({step:index,progress}),show:(i)=>{halt();go(i);}};const observer=typeof ResizeObserver!=='undefined'?new ResizeObserver(()=>{if(!host.hidden)draw();}):null;observer?.observe(el('guide-svg'));window.addEventListener?.('pagehide',()=>{halt(false);observer?.disconnect();},{signal:lifecycle.signal});
if(document.modelContext?.registerTool){const tools=[{name:'read_matrix_walkthrough',title:'Read matrix walkthrough',description:'Read the fixed teaching example, current step, and movement checkpoint.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(i){if(!i||Object.keys(i).length)throw new Error('Expected an empty object.');return{visible:!host.hidden,step:index,title:G.STEPS[index].title,progress,matrix:[...G.matrix],input:[...G.input],checkpoint:G.scene(index,progress).checkpoint};}},{name:'show_matrix_walkthrough_step',title:'Show a matrix walkthrough step',description:'Open the guided example and display a teaching step from 0 to 6. Stops automatic playback.',inputSchema:{type:'object',properties:{step:{type:'integer',minimum:0,maximum:6}},required:['step'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(i){if(!i||Object.keys(i).some(k=>k!=='step')||!Number.isInteger(i.step)||i.step<0||i.step>6)throw new Error('Provide a step from 0 to 6.');if(options.canVisitStep?.(i.step)===false)throw new Error('Record the lesson prediction before opening this step.');halt();el('guide-mode')?.click();index=i.step;progress=1;controls();draw();return{step:index,displayed:true};}}];for(const t of tools)try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
controls();draw();return{dispose:()=>{halt(false);observer?.disconnect();lifecycle.abort();},refresh:controls};
}
window.mountMatrixGuide=mountMatrixGuide;
if(document.getElementById('guided-workspace'))mountMatrixGuide();
})();
